"""Offline M20.2 acceptance cases with PDFs generated by the pinned PyMuPDF."""

from dataclasses import asdict
from hashlib import sha256
import json
from pathlib import Path

import pymupdf
import pytest

from experiments.m20 import localize
from experiments.m20.corrections import InvalidCorrections
from experiments.m20.localization_text import PageMatcher, extract_runs, normalized, page_bounds


FONT = (Path(__file__).resolve().parents[2] / "src" / "pdf_annotator" / "assets" / "fonts"
        / "SourceSans3-Regular.ttf")


@pytest.fixture
def document():
    with pymupdf.open() as doc:
        doc.new_page(width=450, height=300)
        yield doc


def proposal(text=None, *, operation="replace", before=None, after=None, page=0, side=None):
    return {
        "operation": operation, "original_text": text if operation != "insert" else None,
        "context_before": before, "context_after": after, "page_index": page,
        "insert_anchor": {"text": text, "side": side} if operation == "insert" else None,
        "replacement_text": "è " if operation in ("replace", "insert") else None,
        "reason": "Motivazione della fixture.", "category": "grammar",
    }


def results(document, *proposals):
    return localize.localize_document(document, list(proposals))


def test_unique_exact_and_no_subword_casefold_or_approximation(document):
    document[0].insert_text((30, 60), "Correggi questo testo, non il pretesto.")
    match, substring, case, fuzzy = results(
        document, proposal("testo"), proposal("est"), proposal("Testo"), proposal("tasto"),
    )
    assert (match.status, match.applicable, match.candidate_count) == ("text_exact", True, 1)
    assert match.matched_text == "testo" and len(match.quads) == 1
    assert all(r.status == "unresolved" and not r.applicable and not r.quads
               for r in (substring, case, fuzzy))


def test_repeat_requires_consistent_immediate_context(document):
    document[0].insert_text((25, 60), "Uno testo sopra. Due testo sotto. Tre testo sotto.")
    repeated, selected, conflicting, still_repeated = results(
        document, proposal("testo"), proposal("testo", before="Due ", after=" sotto", operation="delete"),
        proposal("testo", before="Uno ", after=" sotto"), proposal("testo", after=" sotto"),
    )
    assert repeated.status == "ambiguous" and repeated.candidate_count == 3
    assert selected.status == "text_exact" and selected.context_match_count == 1
    assert selected.source_range["start"] == len("Uno testo sopra. Due ")
    assert conflicting.status == "ambiguous" and conflicting.context_match_count == 0
    assert still_repeated.status == "ambiguous" and still_repeated.context_match_count == 2
    assert all(not r.applicable and not r.quads for r in (repeated, conflicting, still_repeated))


def test_context_cannot_disambiguate_using_part_of_a_longer_word(document):
    document[0].insert_text((25, 60), "Contorno bersaglio sottotetto. Centro bersaglio altrove.")
    suffix, prefix, confirmed = results(
        document, proposal("bersaglio", after="sotto"), proposal("bersaglio", before="torno"),
        proposal("bersaglio", before="Centro", after="altrove"),
    )
    assert all(r.status == "ambiguous" and r.context_match_count == 0 and not r.applicable
               for r in (suffix, prefix))
    assert confirmed.status == "text_exact" and confirmed.applicable


def test_multiline_space_normalization_maps_to_ordered_quads(document):
    document[0].insert_text((30, 60), "Prima tre   parole\n    sulla riga dopo.")
    match, = results(document, proposal("tre parole sulla riga"))
    assert match.status == "text_normalized" and match.candidate_count == 1
    assert match.matched_text == "tre   parole\n    sulla riga"
    first, second = match.quads
    assert first[0][1] < second[0][1]
    assert first[0][0] > 30 and second[0][0] > 30
    assert second[1][0] < document[0].search_for("dopo")[0].x0


def test_exact_match_across_font_spans(document):
    page = document[0]
    page.insert_text((30, 60), "Prima ", fontname="helv")
    end = 30 + pymupdf.get_text_length("Prima ", fontname="helv", fontsize=11)
    page.insert_text((end, 60), "prova", fontname="hebo")
    spans = page.get_text("dict")["blocks"][0]["lines"][0]["spans"]
    assert len(spans) == 2
    match, = results(document, proposal("Prima prova"))
    assert match.status == "text_exact" and len(match.quads) == 1


def test_line_end_hyphen_keeps_source_and_glyph_geometry(document):
    document[0].insert_text((30, 60), "Una silla-\nbazione corretta.")
    match, wrong = results(document, proposal("sillabazione"), proposal("silabazione"))
    assert match.status == "text_normalized" and match.matched_text == "silla-\nbazione"
    assert len(match.quads) == 2 and match.quads[0][1][0] >= document[0].search_for("-")[0].x1 - .001
    assert not wrong.applicable


def test_code_keeps_exact_whitespace_and_does_not_dehyphenate(document):
    document[0].insert_text((30, 60), "    return 0;\n    foo-\n    bar", fontname="cour")
    with_indent, at_semicolon, subtraction = results(
        document, proposal("    return 0;"), proposal("return 0;", operation="insert", side="after"),
        proposal("foobar"),
    )
    assert with_indent.status == "text_exact" and with_indent.matched_text.startswith("    ")
    assert at_semicolon.insertion["point"][0] == pytest.approx(document[0].search_for(";")[0].x1)
    assert subtraction.status == "unresolved"


def test_unicode_normalization_keeps_punctuation_and_original_glyphs(document):
    document[0].insert_text((30, 60), "l’equazione\u00a0è finita.", fontname="CoverFont", fontfile=str(FONT))
    match, = results(document, proposal("l'equazione e\u0300 finita."))
    assert match.status == "text_normalized" and len(match.quads) == 1
    assert match.matched_text.startswith("l’equazione") and "è" in match.matched_text
    view = normalized("e\u0300\u00a0ﬁ")
    assert view.text == "è fi" and view.source_spans == ((0, 2), (2, 3), (3, 4), (3, 4))


def test_no_join_between_unrelated_columns_or_blocks(document):
    page = document[0]
    page.insert_text((30, 60), "Colonna sinistra.")
    page.insert_text((245, 60), "Colonna destra.")
    page.insert_text((30, 130), "Paragrafo separato.")
    cross_column, cross_block = results(
        document, proposal("sinistra. Colonna"), proposal("destra. Paragrafo"),
    )
    assert all(r.status == "unresolved" and not r.applicable for r in (cross_column, cross_block))


@pytest.mark.parametrize("rotation", [0, 90])
def test_insertion_sides_follow_glyph_direction(document, rotation):
    page = document[0]
    page.insert_text((80, 130), "ancora", rotate=rotation)
    before, after = results(document, proposal("ancora", operation="insert", side="before"),
                            proposal("ancora", operation="insert", side="after"))
    assert before.status == after.status == "text_exact"
    assert before.insertion["side"] == "before" and after.insertion["side"] == "after"
    if rotation == 0:
        assert before.insertion["point"][0] == pytest.approx(80)
        assert after.insertion["point"][0] > 80
    else:
        assert before.insertion["point"][1] == pytest.approx(130)
        assert after.insertion["point"][1] < 130


def test_repeated_insertion_anchor_needs_context_at_the_boundary(document):
    document[0].insert_text((30, 60), "A return 0; primo. B return 0; secondo.")
    ambiguous, confirmed, conflicting = results(
        document, proposal("return 0;", operation="insert", side="after", before="return 0;"),
        proposal("return 0;", operation="insert", side="after", before="B return 0;", after=" secondo"),
        proposal("return 0;", operation="insert", side="after", before="A return 0;", after=" secondo"),
    )
    assert ambiguous.status == conflicting.status == "ambiguous"
    assert ambiguous.context_match_count == 2 and conflicting.context_match_count == 0
    assert not ambiguous.applicable and ambiguous.insertion is None
    assert confirmed.status == "text_exact" and confirmed.context_match_count == 1
    assert confirmed.insertion["point"][0] == pytest.approx(document[0].search_for("return 0;")[1].x1)


def test_comments_anchor_or_fall_back_by_page(document):
    page = document[0]
    page.insert_text((30, 60), "Prima Acquisisci(); poi continua. testo ripetuto ripetuto")
    anchored, contextual, ambiguous, generic, invalid = results(
        document, proposal("Acquisisci();", operation="comment"),
        proposal(operation="comment", before="Acquisisci();", after="poi continua"),
        proposal("ripetuto", operation="comment"), proposal(operation="comment"),
        proposal(operation="comment", page=1),
    )
    assert anchored.status == contextual.status == "text_exact" and anchored.comment_position == contextual.comment_position
    assert ambiguous.status == generic.status == "page_fallback" and ambiguous.applicable and generic.applicable
    assert ambiguous.candidate_count == 2 and generic.reason == "no_text_reference"
    assert ambiguous.comment_position != generic.comment_position
    assert not generic.quads and generic.source_range is None
    assert invalid.status == "unresolved" and not invalid.applicable and invalid.comment_position is None


def test_fallback_avoids_occupied_top_area_and_is_stable(document):
    page = document[0]
    page.draw_rect((410, 0, 450, 125), fill=(.8, .8, .8))
    items = [proposal(operation="comment") for _ in range(5)]
    first = results(document, *items)
    assert [asdict(x) for x in first] == [asdict(x) for x in results(document, *items)]
    positions = {tuple(result.comment_position) for result in first}
    assert len(positions) == len(items)
    assert all(0 <= x < 410 and 0 <= y < 75 for x, y in positions)


def test_image_only_has_no_precise_target(document):
    with pymupdf.open() as source:
        page = source.new_page(width=200, height=100)
        page.insert_text((15, 30), "Sola immagine")
        pixmap = page.get_pixmap()
        document[0].insert_image((15, 15, 215, 115), pixmap=pixmap)
    replacement, comment = results(document, proposal("Sola immagine"),
                                   proposal("Sola immagine", operation="comment"))
    assert replacement.status == "unresolved" and replacement.reason == "no_native_text_on_page"
    assert replacement.quads == [] and not replacement.applicable
    assert comment.status == "page_fallback" and comment.applicable


@pytest.mark.parametrize("rotation", [0, 90, 180, 270])
def test_canonical_crop_local_and_rotation(document, rotation):
    document.new_page(width=370, height=490)
    page = document[1]
    page.insert_text((80, 110), "geometria")
    page.set_cropbox(pymupdf.Rect(50, 40, 340, 400))
    page.set_rotation(rotation)
    match, note, missing = results(document, proposal("geometria", page=1),
                                   proposal(operation="comment", page=1), proposal("geometria", page=0))
    assert match.status == "text_exact" and match.quads[0][0][0] == pytest.approx(30)
    assert 58 < match.quads[0][0][1] < 70
    assert 70 < match.quads[0][2][1] < 75
    x, y = note.comment_position
    display_y = {0: y, 90: x, 180: 360 - y, 270: 290 - x}[rotation]
    assert 0 <= x <= 290 and 0 <= y <= 360 and 0 <= display_y <= 20
    assert missing.status == "unresolved"


def test_cli_schema_hashes_and_sources_unchanged(document, tmp_path, monkeypatch):
    document[0].insert_text((25, 60), "Una prova.")
    pdf, proposals = tmp_path / "original.pdf", tmp_path / "corrections.json"
    document.save(pdf)
    items = [proposal("prova"), proposal(operation="comment", page=99), proposal(operation="comment")]
    proposals.write_text(json.dumps({"corrections": items}, ensure_ascii=False), encoding="utf-8")
    pdf_before, proposals_before = pdf.read_bytes(), proposals.read_bytes()
    output_root = tmp_path / "output"
    monkeypatch.setattr(localize, "OUTPUT_ROOT", output_root)
    assert localize.main([str(pdf), str(proposals)]) == 0
    directory, = output_root.iterdir()
    output = json.loads((directory / "localization.json").read_text(encoding="utf-8"))
    assert output.keys() == {"schema_version", "coordinate_system", "document_sha256", "corrections_sha256",
                             "summary", "results"}
    assert output["document_sha256"] == sha256(pdf_before).hexdigest()
    assert output["corrections_sha256"] == sha256(proposals_before).hexdigest()
    assert output["coordinate_system"] == "pymupdf_unrotated_crop_local_points"
    assert output["summary"] == {"total": 3, "text_exact": 1, "text_normalized": 0, "page_fallback": 1,
                                 "ambiguous": 0, "unresolved": 1, "applicable": 2, "not_applicable": 1}
    assert [r["correction_index"] for r in output["results"]] == [0, 1, 2]
    assert output["results"][1]["reason"] == "page_out_of_range"
    assert output["results"][0].keys() == {"correction_index", "operation", "page_index", "searched_text",
                                          "insert_anchor", "status", "applicable", "candidate_count",
                                          "context_match_count", "matched_text", "source_range", "quads",
                                          "insertion", "comment_position", "reason"}
    assert all(len(point) == 2 for point in output["results"][0]["quads"][0])
    assert "page_fallback" in (directory / "localization_report.md").read_text(encoding="utf-8")
    assert pdf.read_bytes() == pdf_before and proposals.read_bytes() == proposals_before


def test_invalid_input_schema_and_empty_list():
    assert localize.read_corrections(b'{"corrections":[]}') == []
    for data in (b'{"corrections":[],"corrections":[]}', b'?', b'{"corrections":[{}]}'):
        with pytest.raises(InvalidCorrections):
            localize.read_corrections(data)


def test_normalized_ambiguity_across_layout_runs(document):
    page = document[0]
    page.insert_text((30, 60), "A due  parole.")
    page.insert_text((30, 140), "B due   parole.")
    bounds = page_bounds(page)
    matcher = PageMatcher(extract_runs(page, bounds), bounds)
    status, candidates = matcher.candidates("due parole")
    assert status == "text_normalized" and len(candidates) == 2
    blocked, confirmed = results(document, proposal("due parole"), proposal("due parole", before="B "))
    assert blocked.status == "ambiguous" and not blocked.applicable
    assert confirmed.status == "text_normalized" and confirmed.matched_text == "due   parole"
